import { lazy } from 'react';
import { FileSignature as IcFileSignature, ListChecks as IcListChecks, UserPlus as IcUserPlus } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Offer & Onboarding — hub page for the Recruitment menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 3 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'OnboardingCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const OfferManagement = lazy(() => import('./OfferManagement'));
const OnboardingChecklist = lazy(() => import('./OnboardingChecklist'));
const EmployeeAutoCreation = lazy(() => import('./EmployeeAutoCreation'));

export const TABS = [
  { id: 'offers', label: 'Offer Management', icon: IcFileSignature, page: 'OfferManagement', Component: OfferManagement },
  { id: 'checklist', label: 'Onboarding', icon: IcListChecks, page: 'OnboardingChecklist', Component: OnboardingChecklist },
  { id: 'create', label: 'Employee Creation', icon: IcUserPlus, page: 'EmployeeAutoCreation', Component: EmployeeAutoCreation },
];

export default function OnboardingCenter({ setPage }) {
  return (
    <TabHub
      icon={IcUserPlus}
      eyebrow="Recruitment"
      title="Offer & Onboarding"
      subtitle="Offer management, the joining checklist and employee record creation"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
